declare(strict_types=1);/** * It's free open-source software released under the MIT License. * * @author Anatoly Fenric <anatoly@fenric.ru> * @copyright Copyright (c) 2018, Anatoly Fenric * @license https://github.com/sunrise-php/http-message/blob/master/LICENSE * @link https://github.com/sunrise-php/http-message */ namespace ComfinoExternal\Sunrise\Http\Message; use InvalidArgumentException; use ComfinoExternal\Psr\Http\Message\ResponseFactoryInterface; use ComfinoExternal\Psr\Http\Message\ResponseInterface; use ComfinoExternal\Psr\Http\Message\StreamInterface; use Stringable; use function json_encode; use function json_last_error; use function json_last_error_msg; use const JSON_ERROR_NONE; class ResponseFactory implements ResponseFactoryInterface{ public function createResponse(int $statusCode=200,string $reasonPhrase=''):ResponseInterface{return new Response($statusCode,$reasonPhrase);} public function createHtmlResponse(int $statusCode,$html):ResponseInterface{$html=(string)$html;$response=new Response($statusCode,null,['Content-Type'=>'text/html; charset=UTF-8']);$response->getBody()->write($html); return $response;} public function createJsonResponse(int $statusCode,$data,int $flags=0,int $depth=512):ResponseInterface{json_encode('');$json=json_encode($data,$flags,$depth); if(JSON_ERROR_NONE!=json_last_error()){throw new InvalidArgumentException(json_last_error_msg());}$response=new Response($statusCode,null,['Content-Type'=>'application/json; charset=UTF-8']);$response->getBody()->write($json); return $response;}}